from django.db import migrations, models


# Etiquetas del catálogo que el formulario ya no ofrece. Se copian al texto
# para que una tarea guardada siga leyéndose igual.
CATALOGO_ANTERIOR = {
    "sillas": "Solicitar sillas y mesas",
    "colacion": "Solicitar colación",
    "regalos": "Solicitar regalos",
    "local": "Reservar local o espacio",
    "animacion": "Contratar animadores o artistas",
    "difusion": "Difusión e invitaciones",
    "otra": "Otra gestión",
}


def texto_libre_desde_catalogo(tipo, descripcion):
    """Arma el texto libre sin perder la etiqueta del catálogo ni el detalle ya escrito."""
    etiqueta = CATALOGO_ANTERIOR.get(tipo or "", (tipo or "").strip())
    texto = (descripcion or "").strip()
    if (tipo or "") == "otra":
        return texto or etiqueta
    if not texto or texto.casefold() == etiqueta.casefold():
        return etiqueta
    return f"{etiqueta}: {texto}"


def pasar_catalogo_a_texto(apps, schema_editor):
    Tarea = apps.get_model("servicios", "TareaPreparatoria")
    for tarea in Tarea.objects.all().iterator():
        Tarea.objects.filter(pk=tarea.pk).update(
            tipo="otra",
            descripcion=texto_libre_desde_catalogo(tarea.tipo, tarea.descripcion)[:280],
        )


